package org.emransm.moviebox.phone;
import android.net.Uri;import android.view.*;import androidx.recyclerview.widget.*;import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import java.util.*;import static org.junit.Assert.*;import static org.emransm.moviebox.phone.PhoneMediaScenarios.*;
@RunWith(AndroidJUnit4.class) public class HomeCarouselScenarios {
 static class Feed extends BlockFlowScenarios.FakeApi {final String local;String selected="";Feed()throws Exception{local=Uri.fromFile(fixture()).toString();}public List<JSONObject> home()throws Exception{List<JSONObject> all=new ArrayList<>();for(int n=0;n<100;n++)all.add(new JSONObject().put("subjectId","qa-carousel-"+n).put("title","Owned carousel "+n).put("subjectType",1).put("releaseDate","2026-01-01"));return all;}public JSONObject detail(JSONObject item)throws Exception{return new JSONObject(item.toString());}public List<JSONObject> initialPlayback(JSONObject item,int season,int episode,int quality)throws Exception{selected=item.getString("subjectId");return Collections.singletonList(new JSONObject().put("resourceId","owned-carousel-media").put("resourceLink",local).put("resolution",720));}public List<JSONObject> playback(JSONObject item,int season,int episode)throws Exception{return initialPlayback(item,season,episode,720);}public List<JSONObject> captions(JSONObject item,JSONObject stream){return Collections.emptyList();}}
 static RecyclerView recycler(View root){if(root instanceof RecyclerView)return (RecyclerView)root;if(root instanceof ViewGroup)for(int n=0;n<((ViewGroup)root).getChildCount();n++){RecyclerView found=recycler(((ViewGroup)root).getChildAt(n));if(found!=null)return found;}return null;}
 static int first(ActivityScenario<PhoneActivity> s){int[] value={-1};main(s,a->{RecyclerView r=recycler((View)field(a,"root"));if(r!=null)value[0]=((LinearLayoutManager)r.getLayoutManager()).findFirstVisibleItemPosition();});return value[0];}
 @Test public void hundredSlidesAreRecycledAndLastPlayUsesItsOwnTitle()throws Exception{Feed feed=new Feed();try(ActivityScenario<PhoneActivity>s=ActivityScenario.launch(PhoneActivity.class)){BlockFlowScenarios.isolate(s,feed);main(s,a->call(a,"browse",new Class[]{String.class},"Discover"));waitFor(()->first(s)>=0,5000);main(s,a->{RecyclerView r=recycler((View)field(a,"root"));assertEquals(100,r.getAdapter().getItemCount());assertTrue("Home must recycle featured cards instead of inflating all100",r.getChildCount()<=6);((LinearLayoutManager)r.getLayoutManager()).scrollToPositionWithOffset(99,0);});waitFor(()->{boolean[] ready={false};main(s,a->ready[0]=description((View)field(a,"root"),"Play Owned carousel 99")!=null);return ready[0];},5000);BlockFlowScenarios.clickRoot(s,"Play Owned carousel 99");waitFor(()->playing(s),15000);assertEquals("qa-carousel-99",feed.selected);}}
 @Test public void pauseStopsAutoRotationAndResumeAdvances()throws Exception{Feed feed=new Feed();try(ActivityScenario<PhoneActivity>s=ActivityScenario.launch(PhoneActivity.class)){BlockFlowScenarios.isolate(s,feed);main(s,a->call(a,"browse",new Class[]{String.class},"Discover"));waitFor(()->first(s)>=0,5000);BlockFlowScenarios.clickRoot(s,"Pause featured carousel");int before=first(s);Thread.sleep(7500);assertEquals("Pausedcarousel stays on currenttitle",before,first(s));BlockFlowScenarios.clickRoot(s,"Play featured carousel");waitFor(()->first(s)>before,9000);}}
}
